def poly_grid(P, names, lo=-6, hi=6, desc=None, extra=(), **kw):
    """Grid with polygon `names` (a list of point names) drawn, plus extra items."""
    return grid_fig(P, [('poly', names)] + list(extra), lo=lo, hi=hi, desc=desc, **kw)


